const items = $input.all();

const allowedCourses = {
  "python": "Python",
  "python automation": "Python Automation",
  "machine learning": "Machine Learning",
  "data science": "Data Science",
  "generative ai": "Generative AI",
  "full stack": "Full Stack"
};

function titleCase(value) {
  const text = String(value ?? "").trim();
  if (!text) return "Unknown";

  return text.toLowerCase().replace(/\b[a-z]/g, c => c.toUpperCase());
}

function cleanDate(value) {
  const text = String(value ?? "").trim();

  if (/^\d{4}-\d{2}-\d{2}$/.test(text)) {
    return text;
  }

  // Input example: 23-05-2025 (DD-MM-YYYY)
  const match = text.match(/^(\d{1,2})-(\d{1,2})-(\d{4})$/);

  if (match) {
    const [, day, month, year] = match;
    return `${year}-${month.padStart(2, "0")}-${day.padStart(2, "0")}`;
  }

  // Input example: 9/1/2026 (MM/DD/YYYY)
  const usDate = text.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);

  if (usDate) {
    const [, month, day, year] = usDate;
    return `${year}-${month.padStart(2, "0")}-${day.padStart(2, "0")}`;
  }

  return "";
}

return items.map((item, index) => {
  const row = item.json;

  const courseKey = String(row.Course ?? "").trim().toLowerCase();
  const fee = String(row.Fee_Paid ?? "").trim().toLowerCase();

  return {
    json: {
      Student_ID: String(row.Student_ID ?? "").trim(),
      Name: titleCase(row.Name),
      Email: String(row.Email ?? "").trim().toLowerCase(),
      Phone: String(row.Phone ?? "").trim(),
      Course: allowedCourses[courseKey] ?? titleCase(row.Course),
      Fee_Paid: ["yes", "true", "1"].includes(fee)
        ? "Yes"
        : ["no", "false", "0"].includes(fee)
          ? "No"
          : fee !== "" && Number.isFinite(Number(fee)) && Number(fee) > 0
            ? "Yes"
            : "No",
      City: titleCase(row.City),
      Enrolled_Date: cleanDate(row.Enrolled_Date)
    },
    pairedItem: { item: index }
  };
});
